"""Writes tools/stats/cases_glm.txt: fitglm and the GeneralizedLinearModel object (matrix input)."""
import os
here = os.path.dirname(os.path.abspath(__file__))
PRE = ("Xg=(1:12)'/3; yb=[0 0 0 1 0 0 1 0 1 1 1 1]'; yc=[1 0 2 1 3 2 4 3 6 5 8 9]'; yp=yc+0.5; Xg2=[Xg cos(Xg)]; yn=[2.1 3.9 6.2 7.8 10.1 12.2 13.8 16.1 18.0 20.2 21.9 24.1]'; "
       "tr=[8 8 8 10 10 10 12 12 12 14 14 14]'; ys=[1 2 3 4 5 6 7 8 9 9 10 11]'; ")
L = ["# generated by make_glm_cases.py"]
PROPS = ("m_.Coefficients.Estimate,m_.Coefficients.SE,m_.Coefficients.tStat,m_.Coefficients.pValue,m_.Rsquared.Ordinary,m_.Rsquared.Adjusted,m_.Rsquared.LLR,m_.Rsquared.Deviance,"
         "m_.Rsquared.AdjGeneralized,m_.Deviance,m_.Dispersion,m_.DispersionEstimated,m_.DFE,m_.NumObservations,m_.NumCoefficients,m_.NumPredictors,m_.CoefficientCovariance,"
         "m_.LogLikelihood,m_.ModelCriterion.AIC,m_.ModelCriterion.AICc,m_.ModelCriterion.BIC,m_.ModelCriterion.CAIC,m_.SSE,m_.SST,m_.SSR,m_.Residuals.Raw,m_.Residuals.LinearPredictor,"
         "m_.Residuals.Pearson,m_.Residuals.Anscombe,m_.Residuals.Deviance,m_.Fitted.Response,m_.Fitted.LinearPredictor,char(m_.Formula),m_.Distribution.Name,m_.Link.Name")
def full(call):
    return f"m_ = {call}; r = {{{PROPS}}};"
calls = ["fitglm(Xg,yb,'Distribution','binomial')", "fitglm(Xg,yb,'Distribution','binomial','Link','probit')", "fitglm(Xg,yb,'Distribution','binomial','Link','comploglog')",
         "fitglm(Xg2,yb,'Distribution','binomial')", "fitglm(Xg,yb,'interactions','Distribution','binomial')", "fitglm(Xg,[yc tr],'Distribution','binomial')",
         "fitglm(Xg,yc,'Distribution','poisson')", "fitglm(Xg,yc,'Distribution','poisson','Link','identity')", "fitglm(Xg2,yc,'quadratic','Distribution','poisson')", "fitglm(Xg,yc,'Distribution','poisson','Intercept',false)",
         "fitglm(Xg,yp,'Distribution','gamma')", "fitglm(Xg,yp,'Distribution','gamma','Link','log')", "fitglm(Xg,yp,'Distribution','inverse gaussian')", "fitglm(Xg,yn)", "fitglm(Xg2,yn,'purequadratic')",
         "fitglm(Xg,yn,'Distribution','normal','Link','log')", "fitglm(Xg,ys,'Distribution','poisson','VarNames',{'dose','count'})", "fitglm(Xg,yn,'constant')"]
for c in calls:
    L.append(full(c))
    L.append(f"m_ = {c}; r = evalc('m_');")
for c in ["predict(m_,[1;2])", "predict(m_,[1;2],'Alpha',0.1)", "predict(m_,Xg)"]:
    L.append(f"m_ = fitglm(Xg,yb,'Distribution','binomial'); [a_,b_] = {c}; r = {{a_,b_}};")
    L.append(f"m_ = fitglm(Xg,yc,'Distribution','poisson'); [a_,b_] = {c}; r = {{a_,b_}};")
    L.append(f"m_ = fitglm(Xg,yn); [a_,b_] = {c}; r = {{a_,b_}};")
    L.append(f"m_ = fitglm(Xg,yp,'Distribution','gamma'); [a_,b_] = {c}; r = {{a_,b_}};")
L += ["m_ = fitglm(Xg,yb,'Distribution','binomial'); r = coefCI(m_);", "m_ = fitglm(Xg,yn); r = coefCI(m_,0.1);", "m_ = fitglm(Xg,yc,'Distribution','poisson'); r = coefCI(m_);",
      "m_ = fitglm(Xg,yc,'Distribution','poisson'); r = feval(m_,[1;3]);", "m_ = fitglm(Xg,yb,'Distribution','binomial'); m_.Deviance = 1;",
      "r = fitglm(Xg,yb,'Distribution','foo');", "r = fitglm(Xg);", "r = fitglm();", "r = fitglm(Xg,yb(1:5),'Distribution','binomial');", "r = fitglm(Xg,yc*(-1),'Distribution','poisson');",
      "r = fitglm(Xg,yb*2,'Distribution','binomial');", "r = fitglm(Xg,yn*0,'Distribution','gamma');", "r = fitglm(Xg,yb,'Distribution','binomial','Link','foo');"]
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_glm.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
